[1879109786] = {["ID"] = 1879109786; ["i"] = 6; ["j"] = 11; ["k"] = 3; ["TYPE"] = 103; ["VXP"] = 2000; ["LP"] = 5; ["REP"] = 500; ["FACTION"] = 1879103954; ["TIER"] = 2; ["MIN_LVL"] = 30; ["NAME"] = "La batalla de Forochel"; ["LORE"] = "Descubre cada uno de los campos de batalla clave para controlar la Bahía de Hielo de Forochel."; ["SUMMARY"] = "Find 4 Gauradan camps"; };
[1879109787] = {["ID"] = 1879109787; ["i"] = 6; ["j"] = 11; ["k"] = 4; ["TYPE"] = 103; ["VXP"] = 2000; ["LP"] = 5; ["REP"] = 500; ["FACTION"] = 1879103954; ["TIER"] = 2; ["MIN_LVL"] = 30; ["NAME"] = "Piedras Antiguas de Forochel"; ["LORE"] = "Aunque los Lossoth de Forochel no son grandes constructores, los enanos tuvieron hace mucho tiempo muchas minas y campamentos en el Norte."; ["SUMMARY"] = "Find 5 ancient structures in Forochel"; };
[1879109788] = {["ID"] = 1879109788; ["i"] = 6; ["j"] = 11; ["k"] = 7; ["TYPE"] = 105; ["VXP"] = 2000; ["LP"] = 10; ["REP"] = 300; ["FACTION"] = 1879103954; ["TIER"] = 3; ["NAME"] = "Expedición de Forochel"; ["LORE"] = "Los Lossoth de Forochel están empeñados en una lucha constante contra sus enemigos los Gauredain, contra la salvaje fauna del norte y contra los elementos mismos. Aunque se podría esperar que recibieran la ayuda con gratitud, esta dureza constante también ha generado una fuerte independencia entre su pueblo -- requerirá un gran esfuerzo ganárselos para la causa de los Pueblos Libres de Eriador."; ["SUMMARY"] = "Complete 10 quests in Forochel"; };
[1879109789] = {["ID"] = 1879109789; ["i"] = 6; ["j"] = 11; ["k"] = 6; ["TYPE"] = 105; ["VXP"] = 2000; ["LP"] = 10; ["REP"] = 500; ["FACTION"] = 1879103954; ["TIER"] = 2; ["NAME"] = "Superviviente de Forochel"; ["LORE"] = "El mayor peligro en Forochel es el ambiente hostil en sí. Los vientos cortantes y el hielo han arrebatado la vida de gente más resistente que las garras del kalpa-kita o las lanzas de los Gauredain -- aunque esos peligros son una amenaza cercana."; ["SUMMARY"] = "Complete 20 quests in Forochel"; };
[1879109790] = {["ID"] = 1879109790; ["i"] = 6; ["j"] = 11; ["k"] = 5; ["TYPE"] = 105; ["VXP"] = 2000; ["LP"] = 15; ["REP"] = 700; ["FACTION"] = 1879103954; ["TIER"] = 1; ["NAME"] = "Pionero / Pionera de Forochel"; ["LORE"] = "La salvaje e implacable naturaleza de Forochel mantendría alejados a todos excepto a los más resistentes, pero para aquellos con el espíritu de resistir y prosperar en su ambiente, su llamado puede resultar irresistible al final."; ["SUMMARY"] = "Complete 30 quests in Forochel"; };
[1879109791] = {["ID"] = 1879109791; ["i"] = 6; ["j"] = 11; ["k"] = 10; ["TYPE"] = 106; ["LP"] = 5; ["REP"] = 500; ["FACTION"] = 1879103954; ["TIER"] = 3; ["MIN_LVL"] = 30; ["NAME"] = "Azote de Angmarim"; ["LORE"] = "Parece que los dedos oscuros de Angmar se han extendido incluso al desolado Forochel, sembrando las semillas del conflicto aquí como en todos los lugares que tocan. Aquí al menos, parece que sus preparativos no están listos como en otros lugares, o quizá encuentren poco valor, pues confían principalmente en sus aliados menos confiables -- los Duramano y los salvajes Gauredain -- en lugar de sus bien ordenadas hordas de Orcos y Hombres malvados."; ["SUMMARY"] = "Defeat 100 Angmarim in Forochel"; ["TITLE"] = "Pesadilla de Angmar"; };
[1879109792] = {["ID"] = 1879109792; ["i"] = 6; ["j"] = 11; ["k"] = 9; ["TYPE"] = 106; ["VXP"] = 2000; ["LP"] = 10; ["REP"] = 700; ["FACTION"] = 1879103954; ["TIER"] = 2; ["MIN_LVL"] = 30; ["NAME"] = "Azote de Angmarim (avanzado)"; ["LORE"] = "Parece que en el mejor de los casos los Angmarim están buscando algo, o quizá simplemente mezclando en los conflictos entre los Lossoth y los Gauredain. No parece que sea su propósito una invasión a toda fuerza en Forochel -- al menos, no todavía."; ["SUMMARY"] = "Defeat 200 Angmarim in Forochel"; };
[1879109793] = {["ID"] = 1879109793; ["i"] = 6; ["j"] = 11; ["k"] = 12; ["TYPE"] = 106; ["LP"] = 5; ["REP"] = 500; ["FACTION"] = 1879103954; ["TIER"] = 3; ["MIN_LVL"] = 30; ["NAME"] = "Azote de Duramano"; ["LORE"] = "Las antiguas ruinas enanas salpican el paisaje de Forochel. Siendo los más resistentes de los Pueblos Libres, los enanos afirman que fueron los primeros en asentarse aquí hace mucho tiempo, con la esperanza de encontrar riquezas bajo la tierra helada -- pero la mayoría de estos asentamientos fueron abandonados hace mucho tiempo. Esperando fortalecer sus reclamaciones como herederos legítimos de los antiguos Señores Enanos, los Duramano buscan reconstruir estos asentamientos con la ayuda de sus aliados Angmarim, pero esto ha traído a sus primos los Barbiluengos al norte también, buscando cuestionar sus reclamaciones, sin importar el valor (o la falta del mismo) de las minas aquí."; ["SUMMARY"] = "Defeat 100 Dourhand Dwarves in Forochel"; ["TITLE"] = "Vigilante de las Minas"; };
[1879109794] = {["ID"] = 1879109794; ["i"] = 6; ["j"] = 11; ["k"] = 11; ["TYPE"] = 106; ["VXP"] = 2000; ["LP"] = 10; ["REP"] = 700; ["FACTION"] = 1879103954; ["TIER"] = 2; ["MIN_LVL"] = 30; ["NAME"] = "Azote de Duramano (Avanzado)"; ["LORE"] = "Los intentos de los Duramano de reclamar un descenso legítimo de los Señores Enanos de antaño parecen inútiles en este punto, pues su alianza oscura con Angmar se convierte en conocimiento más común entre los enanos de la Tierra Media -- pero si acaso, este giro de los eventos solo los ha hecho más peligrosos y desesperados, pues ahora luchan por la supervivencia misma de su casa desviada."; ["SUMMARY"] = "Defeat 200 Dourhand Dwarves in Forochel"; };
[1879109795] = {["ID"] = 1879109795; ["i"] = 6; ["j"] = 11; ["k"] = 14; ["TYPE"] = 106; ["LP"] = 5; ["REP"] = 500; ["FACTION"] = 1879103954; ["TIER"] = 3; ["MIN_LVL"] = 30; ["NAME"] = "Azote de Gauredain"; ["LORE"] = "Finalmente llegaste a la tierra natal de los Gauredain -- y viendola, se hace claro cómo llegaron a ser tales brutos poderosos, moldeados por los elementos vicios y las penurias del Forochel, es difícil imaginarselos de otra manera -- y sin embargo los Lossoth aún mantienen los signos de civilización bajo las mismas penurias. ¿Han elegido los Gauredain su camino de esta manera, o es su camino brutal alguna artimaña del Enemigo hace mucho tiempo?"; ["SUMMARY"] = "Defeat 100 Gauradan in Forochel"; ["TITLE"] = "Repulsor de Salvajes"; };
[1879109796] = {["ID"] = 1879109796; ["i"] = 6; ["j"] = 11; ["k"] = 13; ["TYPE"] = 106; ["VXP"] = 2000; ["LP"] = 10; ["REP"] = 700; ["FACTION"] = 1879103954; ["TIER"] = 2; ["MIN_LVL"] = 30; ["NAME"] = "Azote de Gauredain (avanzado)"; ["LORE"] = "Parece ciertamente extraño que dos pueblos como los Gauredain y los Lossoth luchen por reclamar una tierra tan perdida y difícil como Forochel, y sin embargo se esfuerzan sin cesar por ella. Parece que el hogar es el lugar que conoces, y dondequiera que sea, Hombres, enanos, hobbits, Elfos, Orcos -- y lo que sea -- lucharán para defenderlo."; ["SUMMARY"] = "Defeat 200 Gauradan in Forochel"; };
[1879109797] = {["ID"] = 1879109797; ["i"] = 6; ["j"] = 11; ["k"] = 16; ["TYPE"] = 106; ["LP"] = 5; ["REP"] = 500; ["FACTION"] = 1879103954; ["TIER"] = 3; ["MIN_LVL"] = 30; ["NAME"] = "Azote de Sombríos"; ["LORE"] = "Los Gauredain creen que los Macabras son las almas errantes de los de su pueblo que fueron expulsados por su cobardía, condenados a vagar eternamente por los campos de nieve congelada después de morir congelados en el hielo. Sin embargo, aquellos pocos entre los sabios que conocen estas criaturas sospechan que son más probablemente espíritus oscuros dejados vagando por los baldíos del norte mucho después de la caída de su antiguo Señor Oscuro."; ["SUMMARY"] = "Defeat 40 Grims in Forochel"; ["TITLE"] = "el Desgarrador de Hielo"; };
[1879109798] = {["ID"] = 1879109798; ["i"] = 6; ["j"] = 11; ["k"] = 15; ["TYPE"] = 106; ["VXP"] = 2000; ["LP"] = 10; ["REP"] = 700; ["FACTION"] = 1879103954; ["TIER"] = 2; ["MIN_LVL"] = 30; ["NAME"] = "Azote de Sombríos (Avanzado)"; ["LORE"] = "Si hay el más mínimo rastro de un espíritu que alguna vez vivió dentro del Sombrío, parece que no es suficiente para mostrar ninguna señal de compañía o piedad. Al más mínimo signo de calor o vida atacan, aparentemente decididos a extinguirlo en un asalto de granizo aullante y odio."; ["SUMMARY"] = "Defeat 80 Grims in Forochel"; };
[1879109799] = {["ID"] = 1879109799; ["i"] = 6; ["j"] = 11; ["k"] = 18; ["TYPE"] = 106; ["LP"] = 5; ["REP"] = 500; ["FACTION"] = 1879103954; ["TIER"] = 3; ["MIN_LVL"] = 30; ["NAME"] = "Azote de Colmillo de Sable"; ["LORE"] = "Estos gatos salvajes son depredadores de naturaleza particularmente viciosa e indiscriminada. Los Lossoth se aseguran de respetar su territorio durante la caza, para no convertirse en comida de estas criaturas mortales. Igualmente, el ganado que crían está bajo amenaza constante de estas bestias voraces."; ["SUMMARY"] = "Defeat 100 Sabre-tooths in Forochel"; ["TITLE"] = "Rompe-colmillos"; };
[1879109800] = {["ID"] = 1879109800; ["i"] = 6; ["j"] = 11; ["k"] = 17; ["TYPE"] = 106; ["VXP"] = 2000; ["LP"] = 10; ["REP"] = 700; ["FACTION"] = 1879103954; ["TIER"] = 2; ["MIN_LVL"] = 30; ["NAME"] = "Azote de Colmillo de Sable (Avanzado)"; ["LORE"] = "Los gatos Colmillo de Sable son un peligro frecuente y mortal de los bosques de Forochel. Solo los cazadores más valientes entre los Lossoth se atreven a cazar en las proximidades de una guarda de Colmillo de Sable, e incluso ellos ocasionalmente no regresan."; ["SUMMARY"] = "Defeat 200 Sabre-tooths in Forochel"; };
[1879109801] = {["ID"] = 1879109801; ["i"] = 6; ["j"] = 11; ["k"] = 20; ["TYPE"] = 106; ["LP"] = 5; ["REP"] = 500; ["FACTION"] = 1879103954; ["TIER"] = 3; ["MIN_LVL"] = 30; ["NAME"] = "Azote de sierpes"; ["LORE"] = "Los sierpes de Forochel se han adaptado al ambiente eternamente frío, creciendo con un abrigo de escamas extrañamente peludas para protegerse del frío, mientras que sus garras y dientes llevan un frío extraño propio, a menudo causando que aquellos que sufren heridas de ellos sucumban a un frío mortal."; ["SUMMARY"] = "Defeat 100 Worms in Forochel"; ["TITLE"] = "Ira del Invierno"; };
[1879109802] = {["ID"] = 1879109802; ["i"] = 6; ["j"] = 11; ["k"] = 19; ["TYPE"] = 106; ["VXP"] = 2000; ["LP"] = 10; ["REP"] = 700; ["FACTION"] = 1879103954; ["TIER"] = 2; ["MIN_LVL"] = 30; ["NAME"] = "Azote de sierpes (avanzado)"; ["LORE"] = "Es incierto si estos sierpes son nativas del Forochel o si han bajado de las tierras desoladas del norte durante el invierno cuando la Bahía de Hielo está congelada lo suficiente para cruzar. Por supuesto, ya no importa de dónde vinieron, pues están aquí ahora y son una amenaza para todos los que viven en Forochel."; ["SUMMARY"] = "Defeat 200 Worms in Forochel"; };
[1879110246] = {["ID"] = 1879110246; ["i"] = 6; ["j"] = 11; ["k"] = 21; ["TYPE"] = 105; ["LP"] = 5; ["REP"] = 700; ["FACTION"] = 1879103954; ["TIER"] = 1; ["MIN_LVL"] = 43; ["NAME"] = "La comunidad perdida"; ["LORE"] = "La Comunidad Perdida era un grupo valiente que partió de Angmar para encontrar un gran tesoro en Forochel. Desafortunadamente, encontraron algunos problemas en el camino..."; ["SUMMARY"] = "Aid the members of the lost fellowship"; ["TITLE"] = "Héroe / Heroína de los Perdidos"; };
