[1879140055] = {["ID"] = 1879140055; ["i"] = 7; ["j"] = 2; ["k"] = 44; ["TYPE"] = 106; ["LP"] = 5; ["REP"] = 500; ["FACTION"] = 1879143761; ["TIER"] = 3; ["MIN_LVL"] = 47; ["NAME"] = "Azote de Orcos"; ["LORE"] = "La vasta Moria ha sido abandonada por los enanos durante mucho tiempo, pero durante años incontables los orcos han infestados sus túneles oscuros. Han saqueado la antigua ciudad de sus riquezas y construido sus propios grandes guaridas en y debajo de las obras de los enanos."; ["SUMMARY"] = "Defeat 100 Orcs in Moria"; ["TITLE"] = "Enemigo de los orcos"; };
[1879140056] = {["ID"] = 1879140056; ["i"] = 7; ["j"] = 2; ["k"] = 43; ["TYPE"] = 106; ["VXP"] = 2000; ["LP"] = 10; ["REP"] = 700; ["FACTION"] = 1879143766; ["TIER"] = 2; ["MIN_LVL"] = 47; ["NAME"] = "Azote de orcos (avanzado)"; ["LORE"] = "Se rumorea que hay muchos grupos de orcos en Moria cuyos números podrían reducirse: están los que son nativos de Moria, los de clanes dispersos en las cavernas más profundas, y otro gran destacamento, los Durub, que podrían haber llegado más recientemente bajo órdenes de Mordor."; ["SUMMARY"] = "Defeat 200 Orcs in Moria"; };
