[1879201450] = {["ID"] = 1879201450; ["i"] = 2; ["j"] = 5; ["k"] = 15; ["TYPE"] = 106; ["LP"] = 15; ["TIER"] = 2; ["MIN_LVL"] = 65; ["NAME"] = "Templo perdido: Un mal giro..."; ["LORE"] = "Los terrenos del Templo perdido están siendo profanados por mercenarios que trabajan para Ferndúr el Virulento. La enfermedad que han contraído los mercenarios pronto será su fin, pero sería mejor que los derrotaras y asegurases un final rápido e indoloro a su sufrimiento antes de que propaguen esta peligrosa enfermedad más allá de los límites del templo."; ["SUMMARY"] = "Defeat 75 brigands in the Lost Temple"; ["TITLE"] = "Pacificador de la Miseria"; };
[1879201467] = {["ID"] = 1879201467; ["i"] = 2; ["j"] = 5; ["k"] = 20; ["TYPE"] = 106; ["LP"] = 15; ["TIER"] = 2; ["MIN_LVL"] = 65; ["IS_CAP"] = true; ["NAME"] = "Templo perdido: Gran limpieza"; ["LORE"] = "Bajo el templo Rhudaur perdido del Bosque de los Trolls, el Señor Demacrado Ferndúr crea una plaga mortal para diezmar a los pueblos del norte. Debes destruir todos los cadaveres infectados en su cámara antes de derrotar al Señor Demacrado él mismo para asegurarte de que su plaga sea completamente eliminada."; ["SUMMARY"] = "Destroy all the corpses in Ferndúr's chamber on Tier 2 highest level."; ["TITLE"] = "Consuelo para los Muertos"; };
[1879201468] = {["ID"] = 1879201468; ["i"] = 2; ["j"] = 5; ["k"] = 16; ["TYPE"] = 106; ["LP"] = 15; ["TIER"] = 2; ["MIN_LVL"] = 65; ["NAME"] = "Templo perdido: Los enfermos y los muertos"; ["LORE"] = "Los mercenarios que han tenido la idea estúpida de seguir a Ferndúr en las profundidades del Templo perdido han sucumbido a enfermedades o han sido asesinados por el propio Señor Demacrado. Ahora los espíritus de la plaga se han apoderado de sus cadáveres y acechan en las criptas, preparándose para desatar la peste y la muerte en el Norte. Debes destruir tantos como puedas antes de que escapen para propagar la mortal plaga de Ferndúr."; ["SUMMARY"] = "Defeat 150 wights in the crypts of the Lost Temple"; ["TITLE"] = "Purificador / Purificadora de la infestación"; };
[1879201469] = {["ID"] = 1879201469; ["i"] = 2; ["j"] = 5; ["k"] = 17; ["TYPE"] = 106; ["LP"] = 15; ["TIER"] = 2; ["MIN_LVL"] = 65; ["IS_CAP"] = true; ["NAME"] = "Templo perdido: Masacre sincronizada"; ["LORE"] = "La entrada de las criptas situadas bajo el Templo perdido está custodiada por un par de poderosos Angmarim. Hermano y hermana, Angaidh y Sidhág se complementan en la batalla, empuñando tanto hechizos como espadas con un poder oscuro. Para obtener esta hazaña, ambos hermanos deben caer en un intervalo de diez segundos."; ["SUMMARY"] = "Defeat Angaidh and Sidhág within ten seconds of each other on Tier 2 highest level."; ["TITLE"] = "Verdugo Veloz"; };
[1879201491] = {["ID"] = 1879201491; ["i"] = 2; ["j"] = 5; ["k"] = 5; ["TYPE"] = 106; ["LP"] = 15; ["TIER"] = 2; ["MIN_LVL"] = 65; ["NAME"] = "Planes de Thadúr desbaratados"; ["LORE"] = "En la granja abandonada de Cotonorte, Thadúr ha creado un poderoso veneno conocido como Espina Oscura. Thadúr planea desatar su veneno sobre los hobbits desprevenidos. Debes desbaratar sus planes y derrotarlo antes de que el veneno pueda ser liberado."; ["SUMMARY"] = "Defeat Thadúr"; };
