[1879227741] = {["ID"] = 1879227741; ["i"] = 2; ["j"] = 6; ["k"] = 25; ["TYPE"] = 104; ["TIER"] = 1; ["MIN_LVL"] = 75; ["NAME"] = "Torre de Orthanc: Destructor de Anillos"; ["LORE"] = "Saruman aprendió el arte de la forja de anillos y se hizo muchos anillos de poder menores. Su existencia no puede permitirse continuar. Esta hazaña solo se puede completar en el Nivel 2 de la Incursión de la Torre de Orthanc."; ["SUMMARY"] = "Complete 2 deeds and 5 challenges"; };
[1879227752] = {["ID"] = 1879227752; ["i"] = 2; ["j"] = 6; ["k"] = 41; ["TYPE"] = 104; ["LP"] = 5; ["TIER"] = 2; ["MIN_LVL"] = 75; ["NAME"] = "Torre de Orthanc: Fuego y Hielo"; ["LORE"] = "Estos lugartenientes de Saruman se vuelven más poderosos a medida que la batalla se intensifica. Derrota a los hermanos mientras su poder está en su punto más bajo y aprovecha el momento. Esta hazaña solo puede completarse en el Nivel 2 del ala de fuego y hielo de la Incursión de la Torre de Orthanc."; ["SUMMARY"] = "Complete Challenge: Fire and Ice"; };
[1879227753] = {["ID"] = 1879227753; ["i"] = 2; ["j"] = 6; ["k"] = 40; ["TYPE"] = 104; ["LP"] = 5; ["TIER"] = 2; ["MIN_LVL"] = 75; ["NAME"] = "Torre de Orthanc: Bailando en la oscuridad"; ["LORE"] = "El poder de la Sombra es una de las mayores fortalezas que posee el Enemigo. Saruman ha aprovechado este poder y se lo ha dado a su aprendiz en forma de anillo. Cuanto antes derrotes al aprendiz, más rápido se eliminará esa amenaza. Esta hazaña solo se puede completar en el Nivel 2 del ala de la Sombra de la Incursión de la Torre de Orthanc."; ["SUMMARY"] = "Complete Challenge: Dancing in the Dark"; };
[1879227754] = {["ID"] = 1879227754; ["i"] = 2; ["j"] = 6; ["k"] = 39; ["TYPE"] = 104; ["LP"] = 5; ["TIER"] = 2; ["MIN_LVL"] = 75; ["NAME"] = "Torre de Orthanc: Conductividad"; ["LORE"] = "Llevando un anillo con el poder de la tormenta, el troll lugarteniente de Saruman puede electrificar el aire que lo rodea. Quizás si espera hasta que la habitación esté completamente cargada, pueda darle la vuelta a la situación. Esta hazaña solo se puede completar en el Nivel 2 en el ala de rayos de la Incursión de la Torre de Isengard."; ["SUMMARY"] = "Complete Challenge: Conductivity"; };
[1879227755] = {["ID"] = 1879227755; ["i"] = 2; ["j"] = 6; ["k"] = 38; ["TYPE"] = 104; ["LP"] = 5; ["TIER"] = 2; ["MIN_LVL"] = 75; ["NAME"] = "Torre de Orthanc: Lavado ácido"; ["LORE"] = "Los verdaderos guerreros deberían ser capaces de enfrentar sus desafíos sin error. En las profundidades de Isengard, no es diferente. Esta hazaña solo se puede completar en el Nivel 2 en el ala ácida de la Incursión de la Torre de Orthanc."; ["SUMMARY"] = "Complete Challenge: Acid Wash"; };
[1879227756] = {["ID"] = 1879227756; ["i"] = 2; ["j"] = 6; ["k"] = 42; ["TYPE"] = 104; ["LP"] = 5; ["TIER"] = 2; ["MIN_LVL"] = 75; ["NAME"] = "Torre de Orthanc: Cima de Orthanc"; ["LORE"] = "Desde la Cima de Orthanc, Saruman de Muchos Colores -- antes Saruman el Blanco, el más grande de los Magos -- lee las estrellas y contempla su dominio. Enfrentarse a un Mago es una locura, pero enfrentarse a él y sobrevivir es una señal de verdadero heroísmo."; ["SUMMARY"] = "Complete Challenge: Pinnacle of Orthanc"; };
