[1879227974] = {["ID"] = 1879227974; ["i"] = 2; ["j"] = 6; ["k"] = 10; ["TYPE"] = 104; ["LP"] = 5; ["TIER"] = 1; ["MIN_LVL"] = 75; ["NAME"] = "Último árbol en pie"; ["LORE"] = "Cuando todo parece perdido, ¿podrás reunir tu valor y encontrar una manera de ganar? ¡Derrota a los jefes finales de la instancia con un solo Ent en pie. Sé un verdadero héroe!"; ["SUMMARY"] = "Defeat the three trolls with only one Ent left alive."; };
