[1879346400] = {["ID"] = 1879346400; ["i"] = 5; ["j"] = 2; ["k"] = 27; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 117; ["LP"] = 10; ["TIER"] = 1; ["MIN_LVL"] = 32; ["NAME"] = "Enemigo / Enemiga de los Orcos II"; ["LORE"] = "A diferencia de los trasgos, los Orcos han sido criados con una mentalidad marcial y forman la columna vertebral de los ejércitos del Enemigo. No son ni cobardes ni débiles —aunque no pueden aspirar a igualar la destreza marcial de los Elfos—, pero su número y su industria bélica son vastos cuando son movilizados por sus señores sombríos."; ["SUMMARY"] = "Defeat 150 orcs in any area"; };
[1879346402] = {["ID"] = 1879346402; ["i"] = 5; ["j"] = 2; ["k"] = 26; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 117; ["LP"] = 15; ["MIN_LVL"] = 42; ["NAME"] = "Enemigo / Enemiga de los Orcos III"; ["LORE"] = "Aunque los Orcos detestan el sol casi tanto como sus hermanos menores, los trasgos, lo toleran mejor y pueden ser forzados a soportarlo por un tiempo cuando la necesidad —o el látigo de sus amos— lo exige. Aun así, ha sido durante largo tiempo una artimaña del Enemigo conjurar vastas nubes de humo o tinieblas para proteger a sus tropas de los rayos del sol y para ocultar sus movimientos frente a espías y exploradores."; ["SUMMARY"] = "Defeat 250 orcs in any area"; };
