[1879358734] = {["ID"] = 1879358734; ["i"] = 2; ["j"] = 10; ["k"] = 23; ["TYPE"] = 106; ["LP"] = 10; ["TIER"] = 1; ["MIN_LVL"] = 115; ["NAME"] = "El Abismo de Mordath -- Nivel 1"; ["LORE"] = "Decidido a empuñar una vez más el perdido Anillo de Poder Manthríf, el rey Váskmun Dientegrís ha llevado a sus Enanos Cuerno de fuego al Abismo de Mordath, donde ahora descansan los cimientos hundidos de Barad-dûr. Mientras tanto, la Orden del Ojo se ha apresurado a perseguir a los Cuerno de fuego, ansiosa por vengar a sus caídos y disputar la reclamación de los enanos sobre los mayores artefactos del Señor Oscuro. Sin que ninguno de ellos lo sepa, aún mayores son los terrores que Sauron escondió en las sombras del Mordath."; ["SUMMARY"] = "Complete 3 deeds"; ["TITLE"] = "iluminador / iluminadora de los Fosos Negros"; };
