[1879358757] = {["ID"] = 1879358757; ["i"] = 2; ["j"] = 10; ["k"] = 34; ["TYPE"] = 106; ["LP"] = 5; ["TIER"] = 2; ["MIN_LVL"] = 115; ["NAME"] = "El Abismo de Mordath: Una luz en la oscuridad"; ["LORE"] = "En las profundidades del Abismo de Mordath, es el Guardián Amargo quien protege los secretos más ocultos del Señor Oscuro, pero su identidad siempre ha sido un misterio tanto para los esclavos como para los guardias de Mordath. Esta hazaña solo puede completarse en el Nivel 2 de la incursión del Abismo de Mordath."; ["SUMMARY"] = "Defeat Sagróg, the Bitter Warden after fully healing the Unseen Spear and forcing his surrender within 10 seconds on Tier 2"; };
