[1879358760] = {["ID"] = 1879358760; ["i"] = 2; ["j"] = 10; ["k"] = 35; ["TYPE"] = 106; ["LP"] = 5; ["TIER"] = 2; ["MIN_LVL"] = 115; ["NAME"] = "El Abismo de Mordath: La potencia de los anillos de los enanos"; ["LORE"] = "Desesperado por recuperar a Manthríf, el rey Váskmun Dientegrís ha llevado a los Cuerno de Fuego al Abismo de Mordath, pero ¿dónde ha descansado el escurridizo Anillo de los Enanos? Esta hazaña solo se puede completar en el Nivel 2 de la incursión del Abismo de Mordath."; ["SUMMARY"] = "Defeat Fingar the Greedy after fully overcoming every manifestation of Dragon-spell on Tier 2"; };
