[1879370350] = {["ID"] = 1879370350; ["i"] = 2; ["j"] = 11; ["k"] = 39; ["TYPE"] = 104; ["TIER"] = 1; ["MIN_LVL"] = 115; ["NAME"] = "El Saber perdido de los Bastiones Enanos: Thikil-gundu"; ["LORE"] = "Construido por los enanos y robado por los dragones, Thikil-gundu, el Bastión de Acero, ha sido testigo de una historia trágica y terrible."; ["SUMMARY"] = "Discover and compile the Lost Lore of Thikil-gundu"; };
[1879370352] = {["ID"] = 1879370352; ["i"] = 2; ["j"] = 11; ["k"] = 37; ["TYPE"] = 104; ["MIN_LVL"] = 115; ["NAME"] = "Reconquistador / Reconquistadora de Thikil-gundu"; ["LORE"] = "Antes de la llegada de Hrímil Corazónhelado y su vástago, Vethúg Menteinvernal, el Bastión de Acero fue el hogar tanto de los Barbiluengos como de los Zhélruka durante muchos y largos años. Tras la derrota de Vethúg en Erebor, Nori partió con un pequeño grupo para recuperar los tesoros perdidos de Thikil-gundu. Sin embargo, no solo grandes riquezas permanecen ocultas en sus salas heladas, y los enanos del norte pronto tendrán que enfrentarse al verdadero dueño de Thikil-gundu si quieren recuperar lo que se perdió."; ["SUMMARY"] = "Complete 4 deeds and 1 quest"; ["TITLE"] = "Maestro / Maestra del Acero"; };
