[1879442921] = {["ID"] = 1879442921; ["i"] = 2; ["j"] = 14; ["k"] = 27; ["TYPE"] = 106; ["VXP"] = 2000; ["TIER"] = 1; ["MIN_LVL"] = 135; ["NAME"] = "El Tesoro escondido de Abnankâra -- Nivel 5"; ["LORE"] = "Más allá de las cataratas de Amgaruslun, en el Pasohendido, se encuentra el Tesoro escondido de Abnankâra. En su día, fue un antiguo tesoro forjado en secreto por Mótsog y los Martillos Grises durante su rebelión contra los Barbiluengos en los Días Antiguos, y ahora se ha convertido en la guarida de Hrímil Corazónhelado, un temido dragón frío de Morgoth. Dentro de este refugio helado, Hrímil cuida sus heridas y duerme, soñando con vengarse del príncipe Durin y de los enanos Gabil'akkâ."; ["SUMMARY"] = "Complete The Hiddenhoard of Abnankâra -- Tier 5"; ["TITLE"] = "Desafiador de Hrímil Corazónhelado"; };
