[1879457859] = {["ID"] = 1879457859; ["i"] = 2; ["j"] = 15; ["k"] = 47; ["TYPE"] = 106; ["NA"] = 3; ["MIN_LVL"] = 140; ["NAME"] = "Sant Lhoer, los Jardines Emponzoñados -- nivel 3 -- Liderando la carga"; ["LORE"] = "Sant Lhoer, conocido como los Jardines Emponzoñados de Carn Dûm, es un lugar húmedo repleto de plantas, árboles y flores mortales, como pocas o ninguna se han visto antes en la Tierra Media. Más allá de las aguas fétidas de color verde berilo que fluyen por Sant Lhoer, se alzan inmensas estructuras de cristal, incluyendo Bâr Heledh, la Casa de Cristal. Es aquí donde la hechicera Oganuin practica su arte, experimentando con criaturas, plantas y personas por igual. ¿Con qué fin y para qué propósito? Solo se pueden suponer los más oscuros designios."; ["TITLE"] = "Lideró la carga en Sant Lhoer"; };
