[1879457861] = {["ID"] = 1879457861; ["i"] = 2; ["j"] = 15; ["k"] = 8; ["TYPE"] = 106; ["VXP"] = 2000; ["TIER"] = 2; ["MIN_LVL"] = 140; ["NAME"] = "Sant Lhoer, los Jardines Emponzoñados -- nivel"; ["LORE"] = "Sant Lhoer, conocido como los Jardines Emponzoñados de Carn Dûm, es un lugar húmedo repleto de plantas, árboles y flores mortales, como pocas o ninguna se han visto antes en la Tierra Media. Más allá de las aguas fétidas de color verde berilo que fluyen por Sant Lhoer, se alzan inmensas estructuras de cristal, incluyendo Bâr Heledh, la Casa de Cristal. Es aquí donde la hechicera Oganuin practica su arte, experimentando con criaturas, plantas y personas por igual. ¿Con qué fin y para qué propósito? Solo se pueden suponer los más oscuros designios."; ["TITLE"] = "Segador de Sant Lhoer"; };
[1879457863] = {["ID"] = 1879457863; ["i"] = 2; ["j"] = 15; ["k"] = 10; ["TYPE"] = 106; ["VXP"] = 1000; ["TIER"] = 2; ["MIN_LVL"] = 140; ["NAME"] = "Azote de Sant Lhoer"; ["LORE"] = "Dentro de Sant Lhoer, los Jardines Emponzoñados de Carn Dûm, hay criaturas y plantas como ninguna otra en la Tierra Media. Torcidas por aguas convertidas en fétidas por el terrible Helchgam, y más corrompidas por oscuras hechicerías, estas creaciones impías amenazan con derramarse más allá de los límites de Angmar."; ["TITLE"] = "Cosechador de Sant Lhoer"; };
