[1879458701] = {["ID"] = 1879458701; ["i"] = 2; ["j"] = 15; ["k"] = 48; ["TYPE"] = 106; ["NA"] = 3; ["MIN_LVL"] = 140; ["NAME"] = "Thaurisgar, La Bótica Infame -- Nivel 3 -- Liderando la carga"; ["LORE"] = "En las profundidades de Thaurisgar, innumerables criaturas nacidas de experimentos abominables y retorcidos vagan por las sombras, el terrible legado de Aniochán el Torturador. Antes de la caída de Carn Dûm, Aniochán trabajó incansablemente para superar a sus rivales y ganarse el favor del Senecal de Angmar. Entre sus herramientas para dar forma a sus creaciones malvadas se encontraba un curioso líquido conocido como la Bilis de Ifrinn. Se pensaba que se había perdido después de que un experimento desastroso le costara la vida a Aniochán, pero ahora esta sustancia fétida y vil corre el riesgo de ser liberada en el mundo."; ["TITLE"] = "Lideró la carga en Thaurisgar"; };
[1879458702] = {["ID"] = 1879458702; ["i"] = 2; ["j"] = 15; ["k"] = 17; ["TYPE"] = 106; ["VXP"] = 1000; ["TIER"] = 2; ["MIN_LVL"] = 140; ["NAME"] = "Azote de Thaurisgar"; ["LORE"] = "En las profundidades de Thaurisgar, innumerables criaturas nacidas de experimentos abominables y retorcidos vagan por las sombras, el terrible legado de Aniochán el Torturador. Antes de la caída de Carn Dûm, Aniochán trabajó incansablemente para superar a sus rivales y ganarse el favor del Senescal de Angmar. Entre sus herramientas para dar forma a sus creaciones estaba un curioso líquido conocido como la Bilis de Ifrinn. Se pensaba que se había perdido después de que un experimento desastroso le costara la vida a Aniochán, pero ahora esta sustancia fétida y vil corre el riesgo de liberarse en el mundo."; ["TITLE"] = "Purificador de Bilis Vil"; };
[1879458703] = {["ID"] = 1879458703; ["i"] = 2; ["j"] = 15; ["k"] = 15; ["TYPE"] = 106; ["VXP"] = 2000; ["TIER"] = 2; ["MIN_LVL"] = 140; ["NAME"] = "Thaurisgar, La Bótica Infame -- Nivel 2"; ["LORE"] = "En las profundidades de Thaurisgar, innumerables experimentos viles y retorcidos deambulan por las sombras, el terrible legado de Aniochán el Torturador. Antes de la caída de Carn Dûm, Aniochán trabajó incansablemente para superar a sus rivales y ganarse el favor del Senescal de Angmar. Entre sus principales herramientas para dar forma a sus malvadas creaciones se encontraba un curioso licor conocido únicamente como la Bilis de Ifrinn. Se pensaba que se había perdido después de que un experimento desastroso le costara la vida a Aniochán, pero ahora esta sustancia fétida y vil corre el riesgo de ser liberada en el mundo."; ["TITLE"] = "Rompe-frascos"; };
