[1879458707] = {["ID"] = 1879458707; ["i"] = 2; ["j"] = 15; ["k"] = 13; ["TYPE"] = 105; ["VXP"] = 3000; ["TIER"] = 1; ["MIN_LVL"] = 140; ["NAME"] = "Hazañas de Thaurisgar, La Bótica Infame"; ["LORE"] = "En las profundidades de Thaurisgar, innumerables experimentos viles y retorcidos deambulan por las sombras, el terrible legado de Aniochán el Torturador. Antes de la caída de Carn Dûm, Aniochán trabajaba incansablemente para superar a sus rivales y ganarse el favor del Senescal de Angmar. Entre sus principales herramientas para dar forma a sus terribles creaciones se encontraba un curioso ícor conocido únicamente como la Bilis de Ifrinn. Se pensaba que se había perdido después de que un experimento desastroso le costara la vida a Aniochán, pero ahora esta sustancia fétida y vil corre el riesgo de ser liberada en el mundo."; ["TITLE"] = "Senescal de Thaurisgar"; };
