[1879459078] = {["ID"] = 1879459078; ["i"] = 2; ["j"] = 15; ["k"] = 18; ["TYPE"] = 104; ["VXP"] = 1000; ["TIER"] = 2; ["MIN_LVL"] = 140; ["NAME"] = "Alquimia de Thaurisgar"; ["LORE"] = "En las profundidades de Thaurisgar se encuentran los restos de los experimentos más repugnantes y retorcidos de Aniochán el Atormentador. Entre las muchas herramientas utilizadas para dar forma a sus creaciones se encontraba la Bilis de Ifrinn, un ichor fétido elaborado mezclando los ingredientes y sustancias más mortales. Cada ingrediente conlleva efectos nocivos e indeseables. Fue en estas sustancias viles y nocivas donde Aniochán el Atormentador encontró los resultados que aspiraba a lograr."; ["TITLE"] = "el Ayudante del Alquimista"; };
[1879459101] = {["ID"] = 1879459101; ["i"] = 2; ["j"] = 15; ["k"] = 4; ["TYPE"] = 105; ["VXP"] = 3000; ["MIN_LVL"] = 140; ["NAME"] = "Hazañas del renacimiento de Carn Dûm"; ["LORE"] = "Tras la segunda caída de Angmar, el antiguo reino del Rey Brujo quedó prácticamente abandonado. Por desgracia, los últimos representantes de la Corona de Hierro han salido de las sombras y han regresado a la ciudad fortificada de Carn Dûm, buscando hacerse con un artefacto perdido del Rey Brujo de Angmar para dominar a los Pueblos Libres de la Tierra Media."; ["TITLE"] = "Senescal de Angmar"; };
