[1879459431] = {["ID"] = 1879459431; ["i"] = 2; ["j"] = 15; ["k"] = 2; ["TYPE"] = 103; ["MIN_LVL"] = 140; ["NAME"] = "Descubrimiento: Carn Dûm"; ["LORE"] = "Aunque fue prácticamente abandonada durante un tiempo tras la caída del Falso Rey y Senescal de Angmar, Mordirith, los restos de la Corona de Hierro han regresado a Carn Dûm, buscando empuñar un artefacto perdido del Rey Brujo de Angmar para dominar a los Pueblos Libres de la Tierra Media."; };
