[1879474837] = {["ID"] = 1879474837; ["i"] = 10; ["j"] = 2; ["k"] = 1; ["TYPE"] = 105; ["VXP"] = 4000; ["MIN_LVL"] = 137; ["NAME"] = "Hazañas del Cabo de Umbar"; ["LORE"] = "Antaño bajo el dominio de los despiadados Herederos de Castamir, el Cabo de Umbar emerge de un capullo sombrío como una tierra renacida. Los ciudadanos luchan con la libertad recién descubierta, los pecados del pasado y el deseo de aferrarse a los ritos y costumbres de su cultura, mientras son guiados por las manos de la Hermandad de las Monedas."; ["TITLE"] = "Navegante del Cabo"; };
