[1879476790] = {["ID"] = 1879476790; ["i"] = 5; ["j"] = 4; ["k"] = 356; ["TYPE"] = 105; ["LP"] = 20; ["NAME"] = "Respetado / Respetada en el Renacimiento de Gondor"; ["LORE"] = "Tus esfuerzos en nombre del Renacimiento de Gondor te han ganado un gran respeto entre el pueblo de Gondor."; ["TITLE"] = "el Renovador"; };
[1879477448] = {["ID"] = 1879477448; ["i"] = 10; ["j"] = 3; ["k"] = 1; ["TYPE"] = 105; ["VXP"] = 4000; ["MIN_LVL"] = 140; ["NAME"] = "Hazañas de Umbar Baharbêl"; ["LORE"] = "Tras el motín de la Piedra del Mar, Umbar Baharbêl ha sido liberada de los Herederos de Castamir y de sus gobernantes del Imperio de Ordâkh. Bajo el gobierno de la Hermandad de las Monedas, un consejo de siete personas elegidas por los ciudadanos de Umbar Baharbêl, la Ciudad de los Corsarios lucha por renacer como Ciudad Libre; mientras su gente sale de la oscuridad que el Señor Oscuro Sauron proyectó sobre ella hace mucho tiempo, recibe por igual noticias de esperanza y traición."; ["TITLE"] = "de Umbar Baharbêl"; };
[1879477537] = {["ID"] = 1879477537; ["i"] = 10; ["j"] = 3; ["k"] = 3; ["TYPE"] = 105; ["VXP"] = 2000; ["LP"] = 5; ["TIER"] = 2; ["MIN_LVL"] = 140; ["NAME"] = "Relatos de la Ciudad Libre (Final)"; ["LORE"] = "Aunque soportaron muchos años de opresión bajo el gobierno de Balakhôr el Azote, los Herederos de Castamir y el Imperio de Ordâkh, los habitantes de Umbar Baharbêl y la Hermandad de las Monedas, que ahora los lideran, se han mantenido firmes en sus esfuerzos por preservar la Ciudad Libre tras el Motín de la Piedra del Mar."; };
