[1879489366] = {["ID"] = 1879489366; ["i"] = 5; ["j"] = 4; ["k"] = 457; ["TYPE"] = 102; ["VEIL_OF_THE_NINE"] = true; ["MIN_LVL"] = 45; ["NAME"] = "Derrota a cada uno de los Nueve"; ["LORE"] = "Así regresaron los Nazgûl, y con su llegada el poder del Señor Oscuro creció. Sauron reveló su poder a través de sus voces espantosas, que clamaban palabras de ira y terror. Incluso los más valientes se acobardaban y encogían al paso de los Espectros... o permanecían inmóviles, sus armas cayendo de manos que se habían enfriado mientras cedían a pensamientos de oscuridad, miedo y muerte."; ["TITLE"] = "Azote de Nueve"; };
