[1879494529] = {["ID"] = 1879494529; ["i"] = 2; ["j"] = 17; ["k"] = 6; ["TYPE"] = 106; ["VXP"] = 1500; ["TIER"] = 2; ["MIN_LVL"] = 150; ["NAME"] = "Ashunûg, el Templo de los Malditos -- Nivel 3"; ["LORE"] = "Hemos descubierto la existencia de un peligroso culto de adoradores de usan-kûni escondido en nuestro propio territorio. Se hacen llamar Anâkhi y han hecho su hogar dentro de Ashunûg, una mina de sal en el norte de Ambarûl que ha estado abandonada durante mucho tiempo. Solo recientemente nos hemos liberado de Sauron, el Omnividente, y no debemos permitir que este nuevo culto se afiance. Los adoradores del escorpión Anâkhi deben ser expulsados de nuestras tierras."; };
[1879494530] = {["ID"] = 1879494530; ["i"] = 2; ["j"] = 17; ["k"] = 5; ["TYPE"] = 106; ["VXP"] = 500; ["TIER"] = 2; ["MIN_LVL"] = 150; ["NAME"] = "Ashunûg, el Templo de los Malditos -- Nivel 2"; ["LORE"] = "Hemos descubierto la existencia de un peligroso culto de adoradores de usan-kûni escondido en nuestro propio territorio. Se hacen llamar Anâkhi y han hecho su hogar dentro de Ashunûg, una mina de sal en el norte de Ambarûl que ha estado abandonada durante mucho tiempo. Solo recientemente nos hemos liberado de Sauron, el Omnividente, y no debemos permitir que este nuevo culto se afiance. Los adoradores del escorpión Anâkhi deben ser expulsados de nuestras tierras."; };
[1879494531] = {["ID"] = 1879494531; ["i"] = 2; ["j"] = 17; ["k"] = 4; ["TYPE"] = 106; ["VXP"] = 500; ["TIER"] = 2; ["MIN_LVL"] = 150; ["NAME"] = "Ashunûg, el Templo de los Malditos -- Nivel 1"; ["LORE"] = "Hemos descubierto la existencia de un peligroso culto de adoradores de usan-kûni escondido en nuestro propio territorio. Se hacen llamar Anâkhi y han hecho su hogar dentro de Ashunûg, una mina de sal en el norte de Ambarûl que ha estado abandonada durante mucho tiempo. Solo recientemente nos hemos liberado de Sauron, el Omnividente, y no debemos permitir que este nuevo culto se afiance. Los adoradores del escorpión Anâkhi deben ser expulsados de nuestras tierras."; };
[1879494779] = {["ID"] = 1879494779; ["i"] = 2; ["j"] = 17; ["k"] = 12; ["TYPE"] = 106; ["VXP"] = 1500; ["TIER"] = 2; ["MIN_LVL"] = 150; ["NAME"] = "Nirgambâr, la Tumba Inquieta - Nivel 3"; ["LORE"] = "En un valle protegido en el norte de Khûd Zagin se encuentran antiguas tumbas en forma de zigurat de piedra pálida, conocidas colectivamente como Nirgambâr. Los exploradores han informado que uno de los hombres de Zidemel, Andur, habría entrado en Nirgambâr atraído por oscuros susurros. Localiza y detén a Andur antes de que pueda liberar lo que acecha en este lugar maldito."; };
