[1879494784] = {["ID"] = 1879494784; ["i"] = 2; ["j"] = 17; ["k"] = 9; ["TYPE"] = 106; ["VXP"] = 1000; ["TIER"] = 1; ["MIN_LVL"] = 150; ["NAME"] = "Vencedor de Nirgambâr, la Tumba Inquieta"; ["LORE"] = "En un valle protegido en el norte de Khûd Zagin se encuentran antiguas tumbas en forma de zigurat de piedra pálida, conocidas colectivamente como Nirgambâr. Los exploradores han informado que uno de los hombres de Zidemel, Andur, habría entrado en Nirgambâr atraído por oscuros susurros. Localiza y detén a Andur antes de que pueda liberar lo que acecha en este lugar maldito."; ["TITLE"] = "el Domador de Tumbas"; };
[1879495455] = {["ID"] = 1879495455; ["i"] = 2; ["j"] = 17; ["k"] = 15; ["TYPE"] = 106; ["VXP"] = 1000; ["TIER"] = 1; ["MIN_LVL"] = 150; ["NAME"] = "Vencedor de Tûl Zakana, el Pozo del Olvido"; ["LORE"] = "En lo profundo de las tierras devastadas por la guerra de Imhûlar, los lugareños te advierten sobre un campamento Ordâkhai, una especie de puesto comercial. Se conoce como Tûl Zakana, el Pozo del Olvido, cuyas aguas te harán olvidar tus problemas y, si bebes lo suficiente, incluso quién eres. Pero a menos que estés comerciando por esta agua, es mejor mantenerse alejado del Pozo, ya que muchos han desaparecido cerca de él, sin volver a ser vistos. Ahora se te ha encomendado la tarea de investigar el Pozo y sus secretos por las familias de los desaparecidos."; ["TITLE"] = "el Distraído / la Distraída"; };
