[1879498781] = {["ID"] = 1879498781; ["i"] = 2; ["j"] = 17; ["k"] = 31; ["TYPE"] = 106; ["VXP"] = 500; ["TIER"] = 1; ["MIN_LVL"] = 150; ["NAME"] = "Templo de Utug-bûr: Thûr Hin -- Nivel 3"; ["LORE"] = "Al entrar en Thûr Hin, la Guarida de los Niños, el olor te golpea. Polvo y cobre, como sangre en tu boca. Aquí nacieron una docena de guerras, junto con miles de soldados. A lo lejos, puedes escuchar a dos Utûgi discutiendo entre ellos, sus voces resonando por el pasillo mohoso."; };
