[1879500021] = {["ID"] = 1879500021; ["i"] = 2; ["j"] = 17; ["k"] = 1; ["TYPE"] = 106; ["VXP"] = 1000; ["LP"] = 10; ["REP"] = 700; ["FACTION"] = 1879489736; ["MIN_LVL"] = 150; ["NAME"] = "Conflictos del Valle del Ikorbân"; ["LORE"] = "Has demostrado tu valía al derrotar a la secta de los Anâkhi en Ashunûg, al repeler la oscuridad en Nirgambâr, la Tumba Inquieta, al investigar Tûl Zakana, el Pozo del Olvido, y al sobrevivir a lo que se encontraba dentro del Templo de Utug-bûr. Nadie puede cuestionar tu tenacidad y determinación, y al completar todas estas hazañas, has ganado un gran favor en todo el Valle del Ikorbân."; ["TITLE"] = "Buscador de las Sombras de Morgoth"; };
