[1879500027] = {["ID"] = 1879500027; ["i"] = 2; ["j"] = 17; ["k"] = 42; ["TYPE"] = 106; ["NA"] = 3; ["MIN_LVL"] = 145; ["NAME"] = "Templo de Utug-bûr -- Liderando la carga"; ["LORE"] = "Utug-bûr alberga bóvedas ocultas durante mucho tiempo excavadas en la piedra, ocultas por la hechicería desde el final de la Primera Edad. Los Thardúth, uno de los poderosos agentes de Morgoth, criaron a los grandes Orcos Ancianos conocidos como los Utûgi. Sus habitantes han permanecido en un sueño hechicero durante milenios, pero ahora se han despertado y su guarida se ha abierto de nuevo con el paso de la amenaza de Sauron."; ["TITLE"] = "Lideró la Carga en el Templo de Utug-bûr"; };
[1879500028] = {["ID"] = 1879500028; ["i"] = 2; ["j"] = 17; ["k"] = 43; ["TYPE"] = 106; ["NA"] = 3; ["MIN_LVL"] = 145; ["NAME"] = "Templo de Utug-bûr -- Primer Retador"; ["LORE"] = "Utug-bûr alberga bóvedas ocultas excavadas en la piedra, escondidas por la hechicería desde el final de la Primera Edad. Los Thardúth, uno de los poderosos agentes de Morgoth, criaron a los grandes Orcos Ancianos conocidos como los Utûgi. Sus habitantes han permanecido en un sueño hechizado durante milenios, pero ahora han despertado, y su guarida se ha abierto de nuevo con el paso de la amenaza de Sauron."; ["TITLE"] = "Desafiador Original de Gârash, el Vacío"; };
