[1879518736] = {["ID"] = 1879518736; ["i"] = 2; ["j"] = 18; ["k"] = 9; ["TYPE"] = 106; ["VXP"] = 2000; ["TIER"] = 1; ["MIN_LVL"] = 150; ["NAME"] = "Vencedor / Vencedora de Kôth Rau, La Fortaleza de los Lamentos"; ["LORE"] = "Con vista a Damudûr, Kôth Rau sirve como fortaleza para quienes desean someter a los pueblos de An Shêru. Faeron y Rhadrog te han encomendado la misión de entrar en esta fortaleza y derrotar a la hechicera Ombátha y al cruel líder utûgi, Râkdakul. La esperanza es que, con la derrota de estos crueles señores, se rompa el yugo que oprime a quienes están bajo su influencia."; ["TITLE"] = "Vencedor de Kôth Rau"; };
