[1879519203] = {["ID"] = 1879519203; ["i"] = 2; ["j"] = 18; ["k"] = 17; ["TYPE"] = 106; ["VXP"] = 1500; ["TIER"] = 2; ["MIN_LVL"] = 160; ["NAME"] = "Ekal-nêbi, el Palacio Caído -- Nivel 3"; ["LORE"] = "El palacio de Ekal-nêbi es la joya de la corona de Emax Dûl, una opulenta residencia de los gobernantes del reino de Nêshak, Nísaka... y ahora también de Ordâkh. Oculta entre bastidores de la vida palaciega, Thothril la Enredadora, Thardúth de Damudûr, comenzó a ejercer silenciosamente sus encantamientos sobre las mentes de sus habitantes. Ahora que los soldados de la alianza de Mizâdi se encuentran a las puertas del palacio, ella afirma su control definitivo sobre el palacio."; };
