[1879519553] = {["ID"] = 1879519553; ["i"] = 2; ["j"] = 18; ["k"] = 1; ["TYPE"] = 106; ["VXP"] = 3000; ["LP"] = 10; ["REP"] = 700; ["FACTION"] = 1879506206; ["MIN_LVL"] = 150; ["NAME"] = "Conflictos de Mûr Ghala"; ["LORE"] = "Has demostrado tu valía al derrotar a Bârlat y a sus bandidos en las Cuevas del Tesoro de Hurum Kâna; al hacer retroceder la oscuridad en Kôth Rau, la Fortaleza de los Lamentos; al investigar los disturbios en Ekal-nêbi, el Palacio Caído; y al sobrevivir a lo que se escondía en la Locura de Nagakhêdi. Nadie puede cuestionar tu tenacidad y determinación, y al completar todas estas hazañas, te has ganado un gran favor en todo Mûr Ghala."; ["TITLE"] = "Presagio de Luz"; };
[1879520125] = {["ID"] = 1879520125; ["i"] = 2; ["j"] = 18; ["k"] = 21; ["TYPE"] = 106; ["VXP"] = 2000; ["TIER"] = 2; ["MIN_LVL"] = 160; ["NAME"] = "Explorador / Exploradora de 'La Locura de Nagakhêdi' - Nivel 1"; ["LORE"] = "Has demostrado tu valía al conquistar lo que se esconde en las profundidades, marcadas por la plaga, de la Locura de Nagakhêdi."; ["TITLE"] = "Vencedor de la Locura de Nagakhêdi"; };
[1879520126] = {["ID"] = 1879520126; ["i"] = 2; ["j"] = 18; ["k"] = 22; ["TYPE"] = 106; ["VXP"] = 2000; ["TIER"] = 2; ["MIN_LVL"] = 160; ["NAME"] = "Explorador / Exploradora de 'La Locura de Nagakhêdi' - Nivel 2"; ["LORE"] = "Has demostrado tu valía al conquistar lo que se esconde en las profundidades, marcadas por la plaga, de la Locura de Nagakhêdi."; ["TITLE"] = "Pesadilla de la Plaga"; };
[1879520127] = {["ID"] = 1879520127; ["i"] = 2; ["j"] = 18; ["k"] = 37; ["TYPE"] = 106; ["NA"] = 3; ["VXP"] = 2000; ["MIN_LVL"] = 155; ["NAME"] = "La Locura de Nagakhêdi -- Retador original"; ["LORE"] = "Desde hace más de cien años, los elfos de Kintai han luchado contra una misteriosa plaga, aparentemente provocada por el Ruido de la Piedra. Esta ya ha consumido la otrora hermosa Adagím y ahora amenaza al resto de los claros élficos. Una investigación llevada a cabo por los guardabosques Faeron y Rhadrog ha rastreado el origen de la plaga hasta La Locura de Nagakhêdi, pero ¿qué peligros acechan en el interior de esa antigua y abandonada maravilla?"; ["TITLE"] = "Desafiador Original de Zamâktar el Putrescente"; };
